import React, { useEffect, useState } from 'react';
import axios from 'axios';

const AdminFacultyBookings = () => {
    const [bookings, setBookings] = useState([]);

    useEffect(() => {
        axios.get('http://localhost:8082/faculty/bookings')
            .then(response => setBookings(response.data))
            .catch(error => console.error("Error fetching bookings:", error));
    }, []);

    const handleAction = (id, status) => {
        axios.post('http://localhost:8082/faculty/bookings/approve', { booking_id: id, status })
            .then(() => setBookings(bookings.map(b => b.booking_id === id ? { ...b, status } : b)))
            .catch(error => console.error("Error updating booking status:", error));
    };

    return (
        <div>
            <h2>Faculty Booking Requests</h2>
            {bookings.length === 0 ? <p>No requests found</p> :
                bookings.map(b => (
                    <div key={b.booking_id}>
                        <p>{b.faculty_name} ({b.department}) - {b.requested_duration}</p>
                        <p>Reason: {b.reason}</p>
                        <p>Status: {b.status}</p>
                        {b.status === 'Pending' && (
                            <>
                                <button onClick={() => handleAction(b.booking_id, 'Approved')}>Approve</button>
                                <button onClick={() => handleAction(b.booking_id, 'Rejected')}>Reject</button>
                            </>
                        )}
                    </div>
                ))}
        </div>
    );
};

export default AdminFacultyBookings;
